using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.Primitives;
using Avalonia.Interactivity;
using Avalonia.LogicalTree;
using Avalonia.Media.Imaging;
using Avalonia.VisualTree;
using LtcPlayer.App;
using System.Text.Json;
namespace LtcPlayer.Avalonia;

public static class UiCopyVerification
{
 public static async Task RunAsync(MainWindow w,string folder)
 {
  Directory.CreateDirectory(folder);bool failed=false;var results=new List<object>();
  T C<T>(string name)where T:Control=>w.FindControl<T>(name)!;
  void Check(bool ok,string why){if(!ok)throw new IOException(why);}
  async Task Test(string name,Func<Task> body){try{await body();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  void Counts(int enabled,int errors){Check(C<TextBlock>("EnabledCueCount").Text==enabled.ToString()&&C<TextBlock>("ErrorCueCount").Text==errors.ToString(),"summary count mismatch");Check(C<TextBlock>("ErrorCueLabel").Foreground!.ToString()==(errors>0?ThemePalette.ErrorText:ThemePalette.SecondaryText).ToString(),"error emphasis mismatch");}
  void Capture(string name){using var image=new RenderTargetBitmap(new PixelSize((int)w.ClientSize.Width,(int)w.ClientSize.Height),new Vector(96,96));image.Render(w);image.Save(Path.Combine(folder,name+".png"));var pane=C<Border>("CoverPane");using var detail=new RenderTargetBitmap(new PixelSize((int)(pane.Bounds.Width*2),(int)(pane.Bounds.Height*2)),new Vector(192,192));detail.Render(pane);detail.Save(Path.Combine(folder,name+"-cover.png"));}
  var a=new CueRow{FilePath=Path.Combine(Program.Option("--fixtures")!,"hap-sync-30s.mov")};CueRow b=null!;
  try{
   await Test("empty summary and current column and delete labels",()=>{Counts(0,0);Check(C<DataGrid>("CueGrid").Columns.Any(c=>c.Header?.ToString()=="ステータス"),"status header absent");Check(C<Button>("DeleteCueButton").Content?.ToString()=="削除"&&!C<Button>("DeleteCueButton").IsEnabled,"empty delete state");return Task.CompletedTask;});
   await ShowProgramService.RefreshAsync(a,CancellationToken.None);b=a.CloneDisabled();b.Enabled=true;b.SetStart("00:01:00:00");w.Editor.Add(a);w.Editor.Add(b);
   await Test("enabled errors exclude disabled cues and recover on validation",()=>{Counts(2,0);b.SourceError="ファイルなし";w.Editor.Validate();Counts(2,1);b.Enabled=false;Counts(1,0);b.ClearSourceError();w.Editor.Validate();Counts(1,0);b.Enabled=true;Counts(2,0);return Task.CompletedTask;});
   await Test("duplicate TC marks both cues and clears after correction",()=>{b.SetStart(a.StartTimecode);Counts(2,2);Check(a.IssueText.Contains("開始TC重複")&&b.IssueText.Contains("開始TC重複")&&w.Editor.Timeline.Length==0,"duplicate exclusion changed");b.SetStart("00:01:00:00");Counts(2,0);return Task.CompletedTask;});
   await Test("multiple selection keeps stable delete label and does no media loading",async()=>{var grid=C<DataGrid>("CueGrid");grid.SelectedItems.Clear();grid.SelectedItems.Add(a);grid.SelectedItems.Add(b);var session=w.Preview.PlaybackSessionId;await Task.Delay(100);Check(C<Button>("DeleteCueButton").Content?.ToString()=="削除"&&C<Button>("DeleteCueButton").IsEnabled&&!C<Button>("CloneCueButton").IsEnabled,"selected command state");Check(w.Preview.PlaybackSessionId==session&&w.Preview.LoadedPath=="","selection loaded video");});
   await Test("blue playing highlight takes precedence and other selected row stays neutral",async()=>{await w.ApplySettingsAsync(new(new(Rate:"25"),VideoRenderer.Displays().First(d=>d.Primary!=0)));await w.ArmAsync();await w.PlayCueForTestAsync(a);var grid=C<DataGrid>("CueGrid");grid.SelectedItems.Clear();grid.SelectedItems.Add(a);grid.SelectedItems.Add(b);await Task.Delay(180);var rows=grid.GetVisualDescendants().OfType<DataGridRow>().ToArray();var playing=rows.First(r=>r.DataContext==a);Check(playing.Background?.ToString()==ThemePalette.PlayingCue.ToString(),"playing background mismatch");Check(playing.Resources["DataGridRowSelectedBackgroundBrush"]?.ToString()==ThemePalette.PlayingCue.ToString(),"selection overrides playing");Check(ThemePalette.Selection.Color.R==ThemePalette.Selection.Color.G&&ThemePalette.Selection.Color.G==ThemePalette.Selection.Color.B,"selection is not neutral");Capture("main-playing-selected");await w.Preview.StopAsync();await w.DisarmAsync();});
   await Test("cover action labels icons and fade survive repeated toggles",async()=>{Check(w.FindControl<TextBlock>("CoverStatus")==null,"status paragraph remains");w.SetFadeSeconds(0);var toggle=C<ToggleButton>("CoverButton");Check(toggle.GetVisualDescendants().OfType<LucideIcon>().Any(i=>i.Kind=="layers-2"),"two-layer icon missing");Check(C<Button>("ChooseCoverButton").GetVisualDescendants().OfType<LucideIcon>().Any(i=>i.Kind=="image-plus"),"change icon missing");foreach(bool visible in new[]{false,true,false,true}){toggle.IsChecked=visible;toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(40);Check(w.Cover.IsCovered==visible&&C<TextBlock>("CoverActionLabel").Text==(visible?"非表示":"表示"),"cover label or toggle changed");}Capture("cover-visible");w.SetCoverVisible(false);w.SetFadeSeconds(1.5m);Check(InputSettings.Load(Program.Option("--settings")).FadeSeconds==1.5,"fade not persisted");var choose=C<Button>("ChooseCoverButton");var clear=C<Button>("ClearCoverButton");Check(Math.Abs(choose.Bounds.Height-clear.Bounds.Height)<.1&&Math.Abs(toggle.Bounds.Height-clear.Bounds.Height)<.1,"control heights differ");var gap=clear.TranslatePoint(default,w)!.Value.X-(choose.TranslatePoint(default,w)!.Value.X+choose.Bounds.Width);Check(gap>=0&&gap<=1,"change and clear have extra gap");Capture("cover-hidden");});
   await Test("settings keep controls and disabled reasons without permanent guidance",async()=>{var display=VideoRenderer.Displays().First(d=>d.Primary!=0);var dialog=new SettingsDialog(new(),display,true,audioEnabled:true);var task=dialog.ShowDialog<SettingsResult?>(w);try{await Task.Delay(100);Check(!dialog.ModeSelector.IsEnabled&&!dialog.OutputSelector.IsEnabled&&!dialog.AudioOutputSelector.IsEnabled,"disabled settings enabled");Check(ToolTip.GetTip(dialog.ModeSelector)?.ToString()=="出力中は変更できません"&&ToolTip.GetTip(dialog.AudioOutputSelector)?.ToString()=="音声出力中は変更できません","disabled reason absent");Check(!dialog.GetLogicalDescendants().OfType<TextBlock>().Any(t=>(t.Text??"").Contains("変更には")||(t.Text??"").Contains("通常は標準")||(t.Text??"").Contains("次のLTC受信から")),"permanent guidance remains");Check(dialog.ModeSelector.ItemCount==2,"mode choices absent");using var image=new RenderTargetBitmap(new PixelSize((int)dialog.ClientSize.Width,(int)dialog.ClientSize.Height),new Vector(96,96));image.Render(dialog);image.Save(Path.Combine(folder,"settings.png"));}finally{dialog.Close(null);await task;}});
  }catch(Exception e){failed=true;File.WriteAllText(Path.Combine(folder,"fatal.txt"),e.ToString());}
  finally{await w.DisarmAsync();await w.Coordinator.DisposeAsync();await w.Preview.DisposeAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
